```lua
snort_ml_engine = {
    http_param_models = {
        { path = "/etc/snort/1_dos_0/ml_models/snort.model" },
        { path = "/etc/snort/1_dos_0/ml_models/pablo_model.model" }
    },
    ftp_cmd_models = {
        { path = "/etc/snort/1_dos_0/ml_models/snort.model" },
    },
}

snort_ml = {
    http_param_threshold = 0.95,
    ftp_cmd_threshold = 0.01,
    client_body_depth = 100,
    uri_depth = -1,
    ftp_request_depth = 10000,
    ftp_response_depth = 1000
}



```

